    pub(crate) generation: u64,
    pub(crate) root: SceneId,
    pub(crate) scenes: Vec<SceneData>,
    pub(crate) animation: OwnedAnimation,
    pub(crate) ignored: [Ignored; 4],
    pub(crate) stats: MemoryStats,
}
impl SceneGraph {
    pub fn scene_id(&self, index: usize) -> Option<SceneId> {
        let scene = self.scenes.get(index)?;
        Some(SceneId {
            owner: self.owner,
            slot: u32::try_from(index).ok()?,
            serial: scene.serial,
        })
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn source(&self) -> &[u8] {
        self.source.as_slice()
    }
    pub fn generation(&self) -> u64 {
        self.generation
    }
    pub fn root(&self) -> SceneView<'_> {
        self.scene(self.root).expect("validated root")
    }
    pub fn scene(&self, id: SceneId) -> Option<SceneView<'_>> {
        let scene = self.scenes.get(id.index())?;
        if id.owner != self.owner || id.serial != scene.serial {
            return None;
        }
        Some(scene.view(
            self.owner,
            id.index(),
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
        ))
    }
    pub fn scene_count(&self) -> usize {
        self.scenes.len()
    }
    pub fn animation(&self) -> AnimationView<'_> {
        self.animation.view()
    }
    pub fn ignored(&self, kind: IgnoredKind) -> Ignored {
        self.ignored[kind as usize]
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
}

//! Scoped decoder draft authorization. Tokens contain values, not builder
//! borrows, so an engine can own its builder and pending draft without selfrefs.
use crate::types::{invalid, stopped};
use crate::*;
#[derive(Debug, Clone, Copy)]
pub(crate) struct ActiveDraft {
    pub scene: SceneId,
    pub nonce: u64,
    pub scene_count: usize,
}
#[derive(Debug)]
pub struct DraftToken {
    pub(crate) mark: BuildMark,
    pub(crate) nonce: u64,
    pub(crate) scene_count: usize,
    ignored: [Ignored; 4],
}
impl SceneBuilder {
    pub fn begin_draft(&mut self, scene: SceneId) -> Result<DraftToken> {
        let i = self.index(scene)?;
        if self.scenes[i].sealed || self.draft_depth >= 64 {
            return Err(invalid(0));
        }
        if let Some(parent) = self.active_draft() {
            if scene.index() < parent.scene_count {
                return Err(invalid(0));
            }
        }
        let nonce = self.serial()?;
        let mark = self.checkpoint_unrestricted(scene)?;
        let scene_count = self.scenes.len();
        self.drafts[self.draft_depth] = Some(ActiveDraft {
            scene,
            nonce,
            scene_count,
        });
        self.draft_depth += 1;
        Ok(DraftToken {
            mark,
            nonce,
            scene_count,
            ignored: self.ignored,
        })
    }
    pub(crate) fn active_draft(&self) -> Option<ActiveDraft> {
        self.draft_depth.checked_sub(1).and_then(|i| self.drafts[i])
    }
    pub(crate) fn draft_index(&self, token: &DraftToken) -> Result<usize> {
        let active = self.active_draft().ok_or_else(|| invalid(0))?;
        if active.scene != token.mark.scene
            || active.nonce != token.nonce
            || active.scene_count != token.scene_count
        {
            return Err(invalid(0));
        }
        let i = self.index(active.scene)?;
        if self.scenes[i].sealed {
            return Err(invalid(0));
        }
        if self.scenes[i]
            .lengths()
            .iter()
            .zip(token.mark.lengths)
            .any(|(now, then)| *now < then)
        {
            return Err(invalid(0));
        }
        Ok(i)
    }
    pub(crate) fn draft_slot(
        &self,
        token: &DraftToken,
        table: usize,
        slot: usize,
        len: usize,
    ) -> Result<usize> {
        let i = self.draft_index(token)?;
        if slot < token.mark.lengths[table] || slot >= len {
            return Err(invalid(0));
        }
        Ok(i)
    }
    /// Validation failure/cancellation leaves the token active and rollbackable.
    pub fn commit_draft(
        &mut self,
        token: &DraftToken,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.draft_index(token)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::scene(self, token.mark.scene, control)?;
        self.draft_depth -= 1;
        self.drafts[self.draft_depth] = None;
        Ok(())
    }
    /// Rollback includes all descendants created after this graph checkpoint.
    /// Cleanup is unconditional even when the caller's work control has stopped.
    pub fn rollback_draft(&mut self, mut token: DraftToken) -> Result<()> {
        let i = self.draft_index(&token)?;
        let mut released = 0;
        for scene in &self.scenes[token.scene_count..] {
            released = crate::memory::add(released, scene.storage_bytes()?)?;
        }
        token.mark.epoch = self.scenes[i].epoch;
        self.rollback_internal(token.mark)?;
        self.scenes.truncate(token.scene_count);
        self.stats.live_bytes -= released;
        self.ignored = token.ignored;
        self.draft_depth -= 1;
        self.drafts[self.draft_depth] = None;
        Ok(())
    }
}

use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_shape(
        &mut self,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<ShapeId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if input.path.edges.len() != input.edge_colors.len() {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes(self, scene, &input.shape, control)?;
        crate::validate::path(&self.source, &input.path, control)?;
        let s = &self.scenes[i];
        for (len, extra, cap, kind) in [
            (s.shapes.len(), 1, self.limits.shapes, LimitKind::Shapes),
            (
                s.edges.len(),
                input.path.edges.len(),
                self.limits.edges,
                LimitKind::Edges,
            ),
            (
                s.path_segments.len(),
                input.path.segments.len(),
                self.limits.commands,
                LimitKind::PathCommands,
            ),
            (
                s.path_numbers.len(),
                input.path.numbers.len(),
                self.limits.numbers,
                LimitKind::PathNumbers,
            ),
        ] {
            if add(len, extra)? > cap {
                return Err(limit(kind));
            }
        }
        let pending = add(
            add(
                add(bytes(&input.path.edges)?, bytes(&input.path.subpaths)?)?,
                add(bytes(&input.path.segments)?, bytes(&input.path.numbers)?)?,
            )?,
            bytes(&input.edge_colors)?,
        )?;
        self.pending(pending)?;
        let serial = self.serial()?;
        room!(self, i, shapes, 1, self.limits.shapes, pending);
        room!(self, i, shapes_serials, 1, self.limits.shapes, pending);
        room!(
            self,
            i,
            edges,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_colors,
            input.edge_colors.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_shape_ids,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            path_subpaths,
            input.path.subpaths.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_segments,
            input.path.segments.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_numbers,
            input.path.numbers.len(),
            self.limits.numbers,
            pending
        );
        let mark = self.checkpoint_internal(scene)?;
        let id = ShapeId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].shapes.len() as u32,
            serial,
        };
        let result = self.publish_shape(i, id, input, control);
        if result.is_err() {
            self.rollback_internal(mark)?;
        }
        result.map(|()| id)
    }
    fn publish_shape(
        &mut self,
        i: usize,
        id: ShapeId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let scene = &mut self.scenes[i];
        let edge_first = scene.edges.len();
        let number_first = scene.path_numbers.len();
        let mut shape = input.shape;
        shape.edges = TableRange {
            first: edge_first,
            count: input.path.edges.len(),
        };
        shape.subpaths = TableRange {
            first: scene.path_subpaths.len(),
            count: input.path.subpaths.len(),
        };
        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            scene.edges.push(edge);
            scene.edge_colors.push(color);
            scene.edge_shape_ids.push(id.slot);
        }
        for mut subpath in input.path.subpaths {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            subpath.first_edge = add(subpath.first_edge, edge_first)?;
            scene.path_subpaths.push(subpath);
        }
        for mut path in input.path.segments {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            path.first_edge = add(path.first_edge, edge_first)?;
            path.first_number = add(path.first_number, number_first)?;
            scene
                .path_segments
                .push(ScenePathSegment { path, shape: id });
        }
        for number in input.path.numbers {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            scene.path_numbers.push(number);
        }
        control.checkpoint().map_err(stopped)?;
        scene.shapes.push(shape);
        scene.shapes_serials.push(id.serial);
        Ok(())
    }
}

use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_transform(
        &mut self,
        scene: SceneId,
        value: TransformFrame,
        control: &mut dyn WorkControl,
    ) -> Result<TransformId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::transform(self, scene, &value, control)?;
        if self.scenes[i].transforms.len() >= self.limits.transforms {
            return Err(limit(LimitKind::Transforms));
        }
        let nested = 0;
        self.pending(nested)?;
        let serial = self.serial()?;
        room!(self, i, transforms, 1, self.limits.transforms, nested);
        room!(
            self,
            i,
            transforms_serials,
            1,
            self.limits.transforms,
            nested
        );
        control.checkpoint().map_err(stopped)?;
        self.retain(nested)?;
        let id = TransformId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].transforms.len() as u32,
            serial,
        };
        self.scenes[i].transforms.push(value);
        self.scenes[i].transforms_serials.push(serial);
        Ok(id)
    }
    pub fn append_clip(
        &mut self,
        scene: SceneId,
        value: Clip,
        control: &mut dyn WorkControl,
    ) -> Result<ClipId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::clip(self, scene, &value, control)?;
        if self.scenes[i].clips.len() >= self.limits.clips {
            return Err(limit(LimitKind::Clips));
        }
        let nested = add(
            bytes(&value.geometry.edges)?,
            bytes(&value.geometry.shapes)?,
        )?;
        self.pending(nested)?;
        let serial = self.serial()?;
        room!(self, i, clips, 1, self.limits.clips, nested);
        room!(self, i, clips_serials, 1, self.limits.clips, nested);
        control.checkpoint().map_err(stopped)?;
        self.retain(nested)?;
        let id = ClipId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].clips.len() as u32,
            serial,
        };
        self.scenes[i].clips.push(value);
        self.scenes[i].clips_serials.push(serial);
        Ok(id)
    }
    pub fn append_pattern(
        &mut self,
        scene: SceneId,
        value: Pattern,
        control: &mut dyn WorkControl,
    ) -> Result<PatternId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::pattern(self, scene, &value, control)?;
        if self.scenes[i].patterns.len() >= self.limits.patterns {
