#[test]
fn stop_byte_work_and_byte_budget_failure_are_transactional() {
    use vexel_base::{BudgetControl, WorkLimits};
    let doc = document();
    let a = template(&doc, false, [100., 100.]);
    let mut b = scene(&doc, Limits::default());
    let root = b.root_id();
    let cancel = std::sync::atomic::AtomicBool::new(false);
    let mut c = BudgetControl::with_limits(
        &cancel,
        u64::MAX,
        WorkLimits::unlimited().with_limit(WorkKind::SourceRead, 0),
    );
    assert!(b
        .publish_template_stops(root, &a, &stops(), &mut c)
        .is_err());
    assert!(b.scene(root).unwrap().stops.is_empty());
    let baseline = b.memory_stats().live_bytes;
    let mut restricted = scene(
        &doc,
        Limits {
            reserved_bytes: baseline,
            ..Limits::default()
        },
    );
    let root = restricted.root_id();
    let before = restricted.memory_stats();
    assert_eq!(
        restricted
            .publish_template_stops(root, &a, &stops(), &mut Run)
            .unwrap_err()
            .kind,
        ErrorKind::Limit(LimitKind::ReservedBytes)
    );
    assert_eq!(restricted.memory_stats(), before);
    restricted.freeze().unwrap();
    b.freeze().unwrap();
}
#[test]
fn source_is_retained_once_and_no_mutable_escape() {
    let doc = document();
    let a = template(&doc, false, [100., 100.]);
    let mut retained = doc.source_owner().clone();
    assert!(Arc::get_mut(&mut retained).is_none());
    let mut b = scene(&doc, Limits::default());
    let root = b.root_id();
    let before = b.memory_stats();
    for n in 0..20 {
        let key = template(&doc, false, [n as f64 + 1., 100.]);
        b.publish_template_stops(root, &key, &stops(), &mut Run)
            .unwrap();
    }
    assert_eq!(b.memory_stats().source_bytes, 4096);
    assert!(b.memory_stats().live_bytes > before.live_bytes);
    let graph = b.freeze().unwrap();
    assert_eq!(graph.memory_stats().source_bytes, 4096);
    drop(doc);
    drop(retained);
    assert!(a.same_template(&a.clone()));
    assert_eq!(graph.source(), SVG);
}

#[test]
fn logarithmic_lookup_reverse_insertion_and_cancelled_hit_keep_prefix() {
    struct Probes(usize);
    impl WorkControl for Probes {
        fn charge(&mut self, kind: WorkKind, units: u64) -> std::result::Result<(), Stop> {
            if kind == WorkKind::ReferenceProbe {
                self.0 += units as usize;
            }
            Ok(())
        }
        fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
            Ok(())
        }
    }
    let doc = document();
    let shared = DecodeSource::new(&doc, &mut Run).unwrap();
    let mut b = scene(&doc, Limits::default());
    let root = b.root_id();
    for n in (0..1024).rev() {
        let a = shared
            .gradient_template_id(definition(&doc, false), [n as f64 + 1., 100.], &mut Run)
            .unwrap();
        b.publish_template_stops(root, &a, &stops(), &mut Run)
            .unwrap();
    }
    let middle = template(&doc, false, [513., 100.]);
    let mut probes = Probes(0);
    let p = b
        .publish_template_stops(root, &middle, &stops(), &mut probes)
        .unwrap();
    assert!(probes.0 <= 11);
    let prefix = b.published_stop_range(root, &p, &mut Run).unwrap();
    let before = b.memory_stats();
    assert!(b
        .publish_template_stops(root, &middle, &stops(), &mut StopAfter(4))
        .is_err());
    assert_eq!(b.memory_stats(), before);
    assert_eq!(b.published_stop_range(root, &p, &mut Run).unwrap(), prefix);
    assert_eq!(b.scene(root).unwrap().stops.len(), 2048);
    b.freeze().unwrap();
}
#[test]
fn nested_child_abort_reclaims_publications_parent_commit_and_freeze_cancel() {
    let doc = document();
    let a = template(&doc, false, [100., 100.]);
    let mut b = scene(&doc, Limits::default());
    let root = b.root_id();
    let parent = b.begin_draft(root).unwrap();
    let child = b.new_scene(viewport()).unwrap();
    let nested = b.begin_draft(child).unwrap();
    let old = b
        .publish_template_stops(child, &a, &stops(), &mut Run)
        .unwrap();
    let leaf = b.new_scene(viewport()).unwrap();
    b.rollback_draft(nested).unwrap();
    assert!(b.scene(leaf).is_err());
    assert!(b.published_stop_range(child, &old, &mut Run).is_err());
    assert!(b.scene(child).unwrap().stops.is_empty());
    assert!(b
        .publish_template_stops(child, &a, &stops(), &mut Run)
        .is_err());
    let retry = b.begin_draft(child).unwrap();
    let fresh = b
        .publish_template_stops(child, &a, &stops(), &mut Run)
        .unwrap();
    assert!(b.published_stop_range(child, &fresh, &mut Run).is_ok());
    assert!(b.published_stop_range(child, &old, &mut Run).is_err());
    b.commit_draft(&retry, &mut Run).unwrap();
    b.seal(child, &mut Run).unwrap();
    b.commit_draft(&parent, &mut Run).unwrap();
    b.freeze().unwrap();
    let mut b = scene(&doc, Limits::default());
    let root = b.root_id();
    b.publish_template_stops(root, &a, &[], &mut Run).unwrap();
    assert_eq!(
        b.freeze_controlled(&mut StopAfter(1)).unwrap_err().kind,
        ErrorKind::Canceled
    );
}
use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_shape(
        &mut self,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<ShapeId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if input.path.edges.len() != input.edge_colors.len() {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes(self, scene, &input.shape, control)?;
        crate::validate::path(&self.source, &input.path, control)?;
        let s = &self.scenes[i];
        for (len, extra, cap, kind) in [
            (s.shapes.len(), 1, self.limits.shapes, LimitKind::Shapes),
            (
                s.edges.len(),
                input.path.edges.len(),
                self.limits.edges,
                LimitKind::Edges,
            ),
            (
                s.path_segments.len(),
                input.path.segments.len(),
                self.limits.commands,
                LimitKind::PathCommands,
            ),
            (
                s.path_numbers.len(),
                input.path.numbers.len(),
                self.limits.numbers,
                LimitKind::PathNumbers,
            ),
        ] {
            if add(len, extra)? > cap {
                return Err(limit(kind));
            }
        }
        let pending = add(
            add(
                add(bytes(&input.path.edges)?, bytes(&input.path.subpaths)?)?,
                add(bytes(&input.path.segments)?, bytes(&input.path.numbers)?)?,
            )?,
            bytes(&input.edge_colors)?,
        )?;
        self.pending(pending)?;
        let serial = self.serial()?;
        room!(self, i, shapes, 1, self.limits.shapes, pending);
        room!(self, i, shapes_serials, 1, self.limits.shapes, pending);
        room!(
            self,
            i,
            edges,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_colors,
            input.edge_colors.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_shape_ids,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            path_subpaths,
            input.path.subpaths.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_segments,
            input.path.segments.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_numbers,
            input.path.numbers.len(),
            self.limits.numbers,
            pending
        );
        let mark = self.checkpoint_internal(scene)?;
        let id = ShapeId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].shapes.len() as u32,
            serial,
        };
        let result = self.publish_shape(i, id, input, control);
        if result.is_err() {
            self.rollback_internal(mark)?;
        }
        result.map(|()| id)
    }
    fn publish_shape(
        &mut self,
        i: usize,
        id: ShapeId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let scene = &mut self.scenes[i];
        let edge_first = scene.edges.len();
        let number_first = scene.path_numbers.len();
        let mut shape = input.shape;
        shape.edges = TableRange {
            first: edge_first,
            count: input.path.edges.len(),
        };
        shape.subpaths = TableRange {
            first: scene.path_subpaths.len(),
            count: input.path.subpaths.len(),
        };
        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            scene.edges.push(edge);
            scene.edge_colors.push(color);
            scene.edge_shape_ids.push(id.slot);
        }
        for mut subpath in input.path.subpaths {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            subpath.first_edge = add(subpath.first_edge, edge_first)?;
            scene.path_subpaths.push(subpath);
        }
        for mut path in input.path.segments {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            path.first_edge = add(path.first_edge, edge_first)?;
            path.first_number = add(path.first_number, number_first)?;
            scene
                .path_segments
                .push(ScenePathSegment { path, shape: id });
        }
        for number in input.path.numbers {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            scene.path_numbers.push(number);
        }
        control.checkpoint().map_err(stopped)?;
        scene.shapes.push(shape);
        scene.shapes_serials.push(id.serial);
        Ok(())
    }
}
